CREATE OR ALTER PROCEDURE [dbo].[uspApprovalDecision_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @ApprovalRequestId UNIQUEIDENTIFIER = NULL
	, @ApprovalStepId UNIQUEIDENTIFIER = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[ApprovalRequestId]
			, t.[ApprovalStepId]
			, t.[DecisionCode]
			, t.[DecidedBy]
			, t.[DecidedAt]
			, t.[Comment]
			, t.[PayloadHash]
			, t.[CreatedDate]
		FROM [dbo].[ApprovalDecision] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[DecisionCode] LIKE CONCAT('%', @SearchText, '%'))
			AND (@ApprovalRequestId IS NULL OR t.[ApprovalRequestId] = @ApprovalRequestId)
			AND (@ApprovalStepId IS NULL OR t.[ApprovalStepId] = @ApprovalStepId)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'approvalRequestId' THEN r.[ApprovalRequestId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'approvalRequestId' THEN r.[ApprovalRequestId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'approvalStepId' THEN r.[ApprovalStepId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'approvalStepId' THEN r.[ApprovalStepId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'decisionCode' THEN r.[DecisionCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'decisionCode' THEN r.[DecisionCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'decidedBy' THEN r.[DecidedBy] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'decidedBy' THEN r.[DecidedBy] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'decidedAt' THEN r.[DecidedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'decidedAt' THEN r.[DecidedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'comment' THEN r.[Comment] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'comment' THEN r.[Comment] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'payloadHash' THEN r.[PayloadHash] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'payloadHash' THEN r.[PayloadHash] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
GO
